-- Isolated Neon cutover branch only. Never run on production.
-- predictions.id is already GENERATED BY DEFAULT AS IDENTITY.
-- Keep its existing identity sequence; only align it with imported IDs.
BEGIN;
SELECT setval(pg_get_serial_sequence('footy_cutover.predictions', 'id'),
  GREATEST(COALESCE((SELECT max(id) FROM footy_cutover.predictions), 0), 1), true);
CREATE UNIQUE INDEX IF NOT EXISTS predictions_match_user_unique
  ON footy_cutover.predictions (match_id, user_id);
COMMIT;
